</div>
<div id="stepTitle" style="font-weight:bold;margin-top:4px">Random polarization before the filter</div>
<div id="stepNarration" style="line-height:1.35">The blue ray travels diagonally across the page while the red E arrows point in many transverse directions.</div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// blue ray → Line + triangular ShapeGeometry arrowhead  #0078a8
// incoming E arrows → eight red ShapeGeometry arrows around a shared center, pickable  #c93a3f
// polarizing filter → tan filled Ellipse ShapeGeometry + orange Line ellipses rim
// filter axis → black double-headed ShapeGeometry arrow through ellipse
// transmitted E → red double-headed ShapeGeometry arrow beyond filter
// component overlay → selected incoming decomposition: red parallel and gray perpendicular double-headed arrows
// leaders → black cubic/wavy BufferGeometry lines
// labels → addLabel HTML labels at source-like positions

const RED = 0xc93a3f;
const BLUE = 0x0078a8;
const ORANGE = 0xf39a55;
const TAN = 0xf5d99b;
const BLACK = 0x111111;
const GRAY = 0x999999;

function mat(color, opacity = 1) {
  return new THREE.MeshBasicMaterial({
    color,
    transparent: opacity < 1,
    opacity,
    depthTest: false,
    side: THREE.DoubleSide
  });
}

function lineMat(color, opacity = 1) {
  return new THREE.LineBasicMaterial({
    color,
    transparent: opacity < 1,
    opacity,
    depthTest: false
  });
}

function makeTriangle(points, material) {
  const shape = new THREE.Shape();
  shape.moveTo(points[0][0], points[0][1]);
  for (let i = 1; i < points.length; i++) shape.lineTo(points[i][0], points[i][1]);
  shape.closePath();
  return new THREE.Mesh(new THREE.ShapeGeometry(shape), material);
}

function makeRect(x0, x1, w, material) {
  const shape = new THREE.Shape();
  shape.moveTo(x0, -w / 2);
  shape.lineTo(x1, -w / 2);
  shape.lineTo(x1, w / 2);
  shape.lineTo(x0, w / 2);
  shape.closePath();
  return new THREE.Mesh(new THREE.ShapeGeometry(shape), material);
}

function createArrow({
  color = RED,
  opacity = 1,
  doubleHeaded = false,
  centered = false,
  width = 0.055,
  head = 0.19,
  headWidth = 0.18
} = {}) {
  const g = new THREE.Group();
  const material = mat(color, opacity);
  g.userData.materials = [material];
  if (doubleHeaded) {
    g.add(makeRect(-0.5 + head, 0.5 - head, width, material));
    g.add(makeTriangle([[0.5, 0], [0.5 - head, headWidth / 2], [0.5 - head, -headWidth / 2]], material));
    g.add(makeTriangle([[-0.5, 0], [-0.5 + head, headWidth / 2], [-0.5 + head, -headWidth / 2]], material));
  } else {
    const x0 = centered ? -0.5 : 0;
    const x1 = centered ? 0.5 : 1;
    g.add(makeRect(x0, x1 - head, width, material));
    g.add(makeTriangle([[x1, 0], [x1 - head, headWidth / 2], [x1 - head, -headWidth / 2]], material));
  }
  g.traverse(o => { o.renderOrder = 4; });
  return g;
}

function setArrowOpacity(g, opacity) {
  g.userData.materials?.forEach(m => {
    m.opacity = opacity;
    m.transparent = opacity < 1;
    m.needsUpdate = true;
  });
}

function setArrowColor(g, color) {
  g.userData.materials?.forEach(m => m.color.set(color));
}

function disposeChildren(g) {
  while (g.children.length) {
    const c = g.children.pop();
    c.geometry?.dispose?.();
    if (Array.isArray(c.material)) c.material.forEach(m => m.dispose?.());
    else c.material?.dispose?.();
  }
}

function rebuildScaledArrow(g, opts, length) {
  disposeChildren(g);
  const fresh = createArrow(opts);
  while (fresh.children.length) g.add(fresh.children.shift());
  g.userData.materials = fresh.userData.materials;
  g.scale.set(length, 1, 1);
}

function addLine(points, color = BLACK, opacity = 1) {
  const geom = new THREE.BufferGeometry().setFromPoints(points);
  const line = new THREE.Line(geom, lineMat(color, opacity));
  line.renderOrder = 2;
  scene.add(line);
  return line;
}

const rayStart = new THREE.Vector3(-5.0, 1.25, 0);
const rayEnd = new THREE.Vector3(5.0, -2.05, 0);
const rayVec = rayEnd.clone().sub(rayStart);
const rayAngle = Math.atan2(rayVec.y, rayVec.x);

const rayLine = addLine([rayStart, rayEnd], BLUE, 1);
rayLine.renderOrder = 1;
const rayHead = makeTriangle([[0, 0], [-0.26, 0.09], [-0.26, -0.09]], mat(BLUE));
rayHead.position.copy(rayEnd);
rayHead.rotation.z = rayAngle;
rayHead.renderOrder = 3;
scene.add(rayHead);

const starGroup = new THREE.Group();
scene.add(starGroup);
const incomingAngles = [0, 45, 90, 135, 180, 225, 270, 315];
const incomingArrows = [];
incomingAngles.forEach((deg, i) => {
  const a = THREE.MathUtils.degToRad(deg);
  const arrow = createArrow({ color: RED, width: 0.055, head: 0.19, headWidth: 0.17 });
  arrow.scale.x = 1.15;
  arrow.rotation.z = a;
  arrow.position.z = 0.04;
  arrow.userData.index = i;
  arrow.userData.angleDeg = deg;
  starGroup.add(arrow);
  incomingArrows.push(arrow);
  registerInteractive(arrow, {
    title: `Incoming E direction ${deg}°`,
    tooltip: 'Click to decompose this incoming E arrow',
    body: 'This one possible incident electric-field direction can be projected onto the polarizer axis. The parallel component is transmitted; the perpendicular component is blocked.',
    onClick: () => selectIncoming(i)
  });
});

const filterGroup = new THREE.Group();
scene.add(filterGroup);
filterGroup.position.set(1.2, -0.30, 0.03);

const filterShape = new THREE.Shape();
filterShape.absellipse(0, 0, 0.375, 1.025, 0, Math.PI * 2, false);
const filterMesh = new THREE.Mesh(new THREE.ShapeGeometry(filterShape), mat(TAN, 0.65));
filterMesh.renderOrder = 2;
filterGroup.add(filterMesh);

function makeEllipseLine(rx, ry, xoff = 0, yoff = 0, color = ORANGE, opacity = 1) {
  const curve = new THREE.EllipseCurve(xoff, yoff, rx, ry, 0, Math.PI * 2, false, 0);
  const pts = curve.getPoints(96).map(p => new THREE.Vector3(p.x, p.y, 0.02));
  const line = new THREE.LineLoop(new THREE.BufferGeometry().setFromPoints(pts), lineMat(color, opacity));
  line.renderOrder = 5;
  return line;
}
filterGroup.add(makeEllipseLine(0.375, 1.025, 0, 0, ORANGE, 1));
filterGroup.add(makeEllipseLine(0.425, 1.10, 0.035, 0, ORANGE, 0.75));
filterGroup.add(makeEllipseLine(0.455, 1.16, -0.035, 0, ORANGE, 0.45));

const axisArrow = createArrow({
  color: BLACK,
  doubleHeaded: true,
  width: 0.025,
  head: 0.12,
  headWidth: 0.12
});
axisArrow.scale.x = 1.75;
axisArrow.position.z = 0.08;
filterGroup.add(axisArrow);

const transmittedArrow = createArrow({
  color: RED,
  doubleHeaded: true,
  width: 0.055,
  head: 0.16,
  headWidth: 0.18
});
transmittedArrow.position.set(3.25, -1.15, 0.05);
scene.add(transmittedArrow);

const componentGroup = new THREE.Group();
scene.add(componentGroup);
const parallelComp = createArrow({ color: RED, doubleHeaded: true, width: 0.04, head: 0.14, headWidth: 0.14 });
const perpComp = createArrow({ color: GRAY, doubleHeaded: true, width: 0.035, head: 0.14, headWidth: 0.13, opacity: 0.35 });
componentGroup.add(parallelComp, perpComp);
componentGroup.visible = false;

function wavyLeader(start, end, amp = 0.045, waves = 2.2) {
  const pts = [];
  const s = new THREE.Vector3(start[0], start[1], start[2] || 0.06);
  const e = new THREE.Vector3(end[0], end[1], end[2] || 0.06);
  const v = e.clone().sub(s);
  const n = new THREE.Vector3(-v.y, v.x, 0).normalize();
  for (let i = 0; i <= 48; i++) {
    const t = i / 48;
    pts.push(s.clone().lerp(e, t).add(n.clone().multiplyScalar(Math.sin(t * Math.PI * 2 * waves) * amp)));
  }
  const line = addLine(pts, BLACK, 1);
  line.renderOrder = 6;
  return line;
}

function curvedLeader(points) {
  const curve = new THREE.CatmullRomCurve3(points.map(p => new THREE.Vector3(p[0], p[1], p[2] || 0.06)));
  const line = addLine(curve.getPoints(40), BLACK, 1);
  line.renderOrder = 6;
  return line;
}

const leaderGroup = new THREE.Group();
scene.add(leaderGroup);
[wavyLeader([1.16, 1.58, 0.08], [1.2, 0.78, 0.08], 0.035, 1.6),
 curvedLeader([[2.55, 0.68, 0.08], [2.30, 0.50, 0.08], [1.42, -0.02, 0.08]]),
 wavyLeader([4.04, 0.58, 0.08], [3.25, -0.58, 0.08], 0.04, 1.5),
 wavyLeader([4.35, -0.88, 0.08], [4.52, -1.88, 0.08], 0.04, 1.7)
].forEach(l => {
  scene.remove(l);
  leaderGroup.add(l);
});

const labels = {
  random: addLabel('Random polarization', new THREE.Vector3(-3.0, 1.70, 0.1), { fontSize: '20px' }),
  dirA: addLabel('Direction of ray<br>(of propagation)', new THREE.Vector3(-2.55, -1.65, 0.1), { fontSize: '18px' }),
  panelA: addLabel('(a)', new THREE.Vector3(-2.62, -2.45, 0.1), { fontSize: '18px' }),
  filter: addLabel('Polarizing filter', new THREE.Vector3(1.23, 1.75, 0.1), { fontSize: '19px' }),
  axis: addLabel('Axis', new THREE.Vector3(2.55, 0.75, 0.1), { fontSize: '18px' }),
  pol: addLabel('Polarization<br>direction', new THREE.Vector3(4.02, 0.85, 0.1), { fontSize: '18px' }),
  dirB: addLabel('Direction<br>of ray', new THREE.Vector3(4.55, -0.18, 0.1), { fontSize: '18px' }),
  panelB: addLabel('(b)', new THREE.Vector3(1.05, -2.45, 0.1), { fontSize: '18px' }),
  e0: addLabel('E&#8407;', new THREE.Vector3(-2.76, 1.44, 0.1), { fontSize: '18px', bold: true }),
  e1: addLabel('E&#8407;', new THREE.Vector3(-1.88, 0.66, 0.1), { fontSize: '18px', bold: true }),
  e2: addLabel('E&#8407;', new THREE.Vector3(-2.20, -0.36, 0.1), { fontSize: '18px', bold: true }),
  e3: addLabel('E&#8407;', new THREE.Vector3(-1.38, 0.64, 0.1), { fontSize: '18px', bold: true }),
  eT: addLabel('E&#8407;', new THREE.Vector3(3.55, -1.12, 0.1), { fontSize: '18px', bold: true })
};

function setLabelVisible(entry, visible) {
  entry.div.style.visibility = visible ? 'visible' : 'hidden';
}

function rotatePointAround(origin, radius, angleDeg, offsetDeg = 0) {
  const a = THREE.MathUtils.degToRad(angleDeg + offsetDeg);
  return new THREE.Vector3(origin.x + radius * Math.cos(a), origin.y + radius * Math.sin(a), 0.1);
}

let selectedIndex = null;
let axisAngle = 90;
let mode = 'Unpolarized only (a)';

function updateELabels() {
  const c = starGroup.position;
  labels.e0.pos.copy(rotatePointAround(c, 0.88, 90, 8));
  labels.e1.pos.copy(rotatePointAround(c, 0.98, 45, 6));
  labels.e2.pos.copy(rotatePointAround(c, 1.02, 315, -8));
  labels.e3.pos.copy(rotatePointAround(c, 1.04, 0, 2));
  const a = THREE.MathUtils.degToRad(axisAngle);
  labels.eT.pos.set(
    transmittedArrow.position.x + Math.cos(a) * 0.32 + 0.18,
    transmittedArrow.position.y + Math.sin(a) * 0.32,
    0.1
  );
}

function updateAxis() {
  document.getElementById('axisReadout').textContent = `${axisAngle}°`;
  const rad = THREE.MathUtils.degToRad(axisAngle);
  axisArrow.rotation.z = rad;
