function wavyLeader(start, end, amp = 0.045, waves = 2.2) {
  const pts = [];
  const s = new THREE.Vector3(start[0], start[1], start[2] || 0.06);
  const e = new THREE.Vector3(end[0], end[1], end[2] || 0.06);
  const v = e.clone().sub(s);
  const n = new THREE.Vector3(-v.y, v.x, 0).normalize();
  for (let i = 0; i <= 48; i++) {
    const t = i / 48;
    pts.push(s.clone().lerp(e, t).add(n.clone().multiplyScalar(Math.sin(t * Math.PI * 2 * waves) * amp)));
  }
  const line = addLine(pts, BLACK, 1);
  line.renderOrder = 6;
  return line;
}

function curvedLeader(points) {
  const curve = new THREE.CatmullRomCurve3(points.map(p => new THREE.Vector3(p[0], p[1], p[2] || 0.06)));
  const line = addLine(curve.getPoints(40), BLACK, 1);
  line.renderOrder = 6;
  return line;
}

