// @FIGURE_CODE_BEGIN
// blue ray → Line plus triangular ShapeGeometry arrowhead, updated to pass through active panel anchors  #0078a8
// incoming unpolarized E starburst → eight red single-headed ShapeGeometry arrows from a common center  #c93a3f
// polarizing filter disk → tan Ellipse ShapeGeometry filled disk with orange LineLoop ellipse rims  #f5d99b/#f39a55
// filter axis → black double-headed ShapeGeometry arrow through ellipse center, slider-rotated
// transmitted E field → red double-headed ShapeGeometry arrow beyond filter, aligned with axis and shrinkable to zero
// selected-component overlay → centered red parallel and faint gray perpendicular double-headed arrows
// callout leaders → black curved/wavy Lines with triangular arrowheads at object endpoints
// text labels → addLabel HTML labels, including clean vector-E symbols made from normal E plus a small over-arrow span

const RED = 0xc93a3f;
const BLUE = 0x0078a8;
const ORANGE = 0xf39a55;
const TAN = 0xf5d99b;
const BLACK = 0x111111;
const GRAY = 0x999999;

const rayAngleFixed = THREE.MathUtils.degToRad(-18.3);
const rayDir = new THREE.Vector3(Math.cos(rayAngleFixed), Math.sin(rayAngleFixed), 0);
const starA = new THREE.Vector3(-3.0, 0.60, 0.04);
const rayStartA = new THREE.Vector3(-5.0, 1.25, 0);
const rayEndA = new THREE.Vector3(5.0, -2.05, 0);
const filterCenterB = new THREE.Vector3(1.20, -0.30, 0.04);
const starB = filterCenterB.clone().add(rayDir.clone().multiplyScalar(-4.20));
const transmittedCenterB = filterCenterB.clone().add(rayDir.clone().multiplyScalar(2.16));
const rayStartB = filterCenterB.clone().add(rayDir.clone().multiplyScalar(-4.95));
const rayEndB = filterCenterB.clone().add(rayDir.clone().multiplyScalar(4.18));

function meshMat(color, opacity = 1) {
  const m = new THREE.MeshBasicMaterial({
    color,
    transparent: opacity < 1,
    opacity,
    depthTest: false,
    side: THREE.DoubleSide
  });
  return m;
}

function basicLineMat(color, opacity = 1) {
  return new THREE.LineBasicMaterial({
    color,
    transparent: opacity < 1,
    opacity,
    depthTest: false
  });
}

function makeTriangle(points, material) {
  const shape = new THREE.Shape();
  shape.moveTo(points[0][0], points[0][1]);
  for (let i = 1; i < points.length; i++) shape.lineTo(points[i][0], points[i][1]);
  shape.closePath();
  return new THREE.Mesh(new THREE.ShapeGeometry(shape), material);
}

function makeRect(x0, x1, w, material) {
  const shape = new THREE.Shape();
  shape.moveTo(x0, -w / 2);
  shape.lineTo(x1, -w / 2);
  shape.lineTo(x1, w / 2);
  shape.lineTo(x0, w / 2);
  shape.closePath();
  return new THREE.Mesh(new THREE.ShapeGeometry(shape), material);
}

function createArrow({
  color = RED,
  opacity = 1,
  doubleHeaded = false,
  centered = false,
  width = 0.055,
  head = 0.22,
  headWidth = 0.18
} = {}) {
  const group = new THREE.Group();
  const material = meshMat(color, opacity);
  group.userData.materials = [material];

  if (doubleHeaded) {
    group.add(makeRect(-0.5 + head, 0.5 - head, width, material));
    group.add(makeTriangle([[0.5, 0], [0.5 - head, headWidth / 2], [0.5 - head, -headWidth / 2]], material));
    group.add(makeTriangle([[-0.5, 0], [-0.5 + head, headWidth / 2], [-0.5 + head, -headWidth / 2]], material));
  } else {
    const x0 = centered ? -0.5 : 0;
    const x1 = centered ? 0.5 : 1;
    group.add(makeRect(x0, x1 - head, width, material));
    group.add(makeTriangle([[x1, 0], [x1 - head, headWidth / 2], [x1 - head, -headWidth / 2]], material));
  }

  group.traverse(o => { o.renderOrder = 4; });
  return group;
}

function setArrowOpacity(group, opacity) {
  group.userData.materials?.forEach(m => {
    m.opacity = opacity;
    m.transparent = opacity < 1;
    m.needsUpdate = true;
  });
}

function addLineTo(parent, points, color = BLACK, opacity = 1, order = 2) {
  const line = new THREE.Line(
    new THREE.BufferGeometry().setFromPoints(points),
    basicLineMat(color, opacity)
  );
  line.renderOrder = order;
  parent.add(line);
  return line;
}

function replaceLinePoints(line, points) {
  const old = line.geometry;
  line.geometry = new THREE.BufferGeometry().setFromPoints(points);
  old?.dispose?.();
}

function vecEHtml() {
  return '<span style="font-weight:bold;position:relative;display:inline-block;line-height:1;padding-top:0.18em;">E<span style="position:absolute;left:0.03em;right:-0.20em;top:-0.58em;font-size:0.78em;font-weight:normal;">&#8594;</span></span>';
}

function sampleCurve(points, steps = 42) {
  const curve = new THREE.CatmullRomCurve3(points.map(p => p.clone ? p.clone() : new THREE.Vector3(p[0], p[1], p[2] ?? 0.09)));
  return curve.getPoints(steps);
}

function sampleWavy(start, end, amp = 0.045, waves = 1.6, steps = 48) {
  const s = start.clone ? start.clone() : new THREE.Vector3(start[0], start[1], start[2] ?? 0.09);
  const e = end.clone ? end.clone() : new THREE.Vector3(end[0], end[1], end[2] ?? 0.09);
  const v = e.clone().sub(s);
  const n = new THREE.Vector3(-v.y, v.x, 0).normalize();
  const pts = [];
  for (let i = 0; i <= steps; i++) {
    const t = i / steps;
    pts.push(s.clone().lerp(e, t).add(n.clone().multiplyScalar(Math.sin(t * Math.PI * 2 * waves) * amp)));
  }
  return pts;
}

function createLeader(parent, points, { wavy = false, amp = 0.04, waves = 1.5 } = {}) {
  const group = new THREE.Group();
  group.userData.opts = { wavy, amp, waves };
  const pts = wavy ? sampleWavy(points[0], points[points.length - 1], amp, waves) : sampleCurve(points);
  const line = addLineTo(group, pts, BLACK, 1, 7);
  const head = makeTriangle([[0, 0], [-0.13, 0.045], [-0.13, -0.045]], meshMat(BLACK));
  head.renderOrder = 8;
  group.add(head);
  group.userData.line = line;
  group.userData.head = head;
  group.userData.setPoints = (nextPoints) => {
    const opts = group.userData.opts;
    const next = opts.wavy ? sampleWavy(nextPoints[0], nextPoints[nextPoints.length - 1], opts.amp, opts.waves) : sampleCurve(nextPoints);
    replaceLinePoints(line, next);
    const a = next[next.length - 2];
    const b = next[next.length - 1];
    head.position.copy(b);
    head.rotation.z = Math.atan2(b.y - a.y, b.x - a.x);
  };
  group.userData.setPoints(points);
  parent.add(group);
  return group;
}

const rayLine = addLineTo(scene, [rayStartA, rayEndA], BLUE, 1, 1);
const rayHead = makeTriangle([[0, 0], [-0.28, 0.095], [-0.28, -0.095]], meshMat(BLUE));
rayHead.renderOrder = 3;
scene.add(rayHead);

function updateRayForMode(isB) {
  const s = isB ? rayStartB : rayStartA;
  const e = isB ? rayEndB : rayEndA;
  replaceLinePoints(rayLine, [s, e]);
  rayHead.position.copy(e);
  rayHead.rotation.z = Math.atan2(e.y - s.y, e.x - s.x);
}

const starGroup = new THREE.Group();
scene.add(starGroup);
const incomingAngles = [0, 45, 90, 135, 180, 225, 270, 315];
const incomingArrows = [];

incomingAngles.forEach((deg, i) => {
  const arrow = createArrow({ color: RED, width: 0.055, head: 0.22, headWidth: 0.18 });
  arrow.rotation.z = THREE.MathUtils.degToRad(deg);
  arrow.scale.x = 1.15;
  arrow.position.z = 0.05;
  arrow.userData.index = i;
  arrow.userData.angleDeg = deg;
  starGroup.add(arrow);
  incomingArrows.push(arrow);
  registerInteractive(arrow, {
    title: `Incoming ${vecEHtml()} direction ${deg}°`,
    tooltip: 'Click to project this incoming E direction onto the filter axis',
    body: 'This incident electric-field direction is decomposed into a component parallel to the polarizer axis and a component perpendicular to it. The parallel component is transmitted; the perpendicular component is blocked.',
    onClick: () => selectIncoming(i)
  });
});

const filterGroup = new THREE.Group();
filterGroup.position.copy(filterCenterB);
scene.add(filterGroup);

const filterShape = new THREE.Shape();
filterShape.absellipse(0, 0, 0.375, 1.025, 0, Math.PI * 2, false);
const filterMesh = new THREE.Mesh(new THREE.ShapeGeometry(filterShape), meshMat(TAN, 0.65));
filterMesh.renderOrder = 2;
filterGroup.add(filterMesh);

function makeEllipseLine(rx, ry, xoff = 0, yoff = 0, color = ORANGE, opacity = 1) {
  const curve = new THREE.EllipseCurve(xoff, yoff, rx, ry, 0, Math.PI * 2, false, 0);
  const pts = curve.getPoints(128).map(p => new THREE.Vector3(p.x, p.y, 0.03));
  const line = new THREE.LineLoop(new THREE.BufferGeometry().setFromPoints(pts), basicLineMat(color, opacity));
  line.renderOrder = 5;
  return line;
}
filterGroup.add(makeEllipseLine(0.375, 1.025, 0, 0, ORANGE, 1));
filterGroup.add(makeEllipseLine(0.425, 1.105, 0.035, 0, ORANGE, 0.72));
filterGroup.add(makeEllipseLine(0.455, 1.155, -0.035, 0, ORANGE, 0.45));

const axisArrow = createArrow({
  color: BLACK,
  doubleHeaded: true,
  width: 0.024,
  head: 0.12,
  headWidth: 0.12
});
axisArrow.scale.x = 1.75;
axisArrow.position.z = 0.09;
filterGroup.add(axisArrow);

const transmittedArrow = createArrow({
  color: RED,
  doubleHeaded: true,
  width: 0.055,
  head: 0.16,
  headWidth: 0.18
});
transmittedArrow.position.copy(transmittedCenterB).setZ(0.06);
transmittedArrow.scale.x = 1.20;
scene.add(transmittedArrow);

const componentGroup = new THREE.Group();
scene.add(componentGroup);
const parallelComp = createArrow({ color: RED, doubleHeaded: true, width: 0.043, head: 0.14, headWidth: 0.14 });
const perpComp = createArrow({ color: GRAY, doubleHeaded: true, width: 0.036, head: 0.14, headWidth: 0.13, opacity: 0.32 });
componentGroup.add(parallelComp, perpComp);
componentGroup.visible = false;

const leaderGroup = new THREE.Group();
scene.add(leaderGroup);

const leaderFilter = createLeader(leaderGroup, [
  new THREE.Vector3(1.20, 1.48, 0.10),
  new THREE.Vector3(1.20, 0.76, 0.10)
], { wavy: true, amp: 0.045, waves: 1.45 });

const leaderAxis = createLeader(leaderGroup, [
  new THREE.Vector3(2.35, 0.62, 0.10),
  new THREE.Vector3(1.45, 0.12, 0.10)
]);

const leaderPol = createLeader(leaderGroup, [
  new THREE.Vector3(4.15, 0.62, 0.10),
  transmittedCenterB.clone().add(new THREE.Vector3(0, 0.55, 0.10))
], { wavy: true, amp: 0.045, waves: 1.2 });

const leaderRayB = createLeader(leaderGroup, [
  new THREE.Vector3(4.60, -0.25, 0.10),
  rayEndB.clone().add(rayDir.clone().multiplyScalar(-0.42)).setZ(0.10)
], { wavy: true, amp: 0.04, waves: 1.25 });

starGroup.position.copy(starA);
updateRayForMode(false);

setCameraView({ projection: 'orthographic', axisScreenAngles: null, rollDeg: 0, heightFraction: 0.72 });

const labels = {
  random: addLabel('Random polarization', new THREE.Vector3(-3.0, 1.70, 0.1), { fontSize: '20px' }),
  dirA: addLabel('Direction of ray<br>(of propagation)', new THREE.Vector3(-2.38, -1.57, 0.1), { fontSize: '18px' }),
  panelA: addLabel('(a)', new THREE.Vector3(-2.34, -2.33, 0.1), { fontSize: '18px' }),
  filter: addLabel('Polarizing filter', new THREE.Vector3(1.23, 1.82, 0.1), { fontSize: '19px' }),
  axis: addLabel('Axis', new THREE.Vector3(2.46, 0.82, 0.1), { fontSize: '18px' }),
  pol: addLabel('Polarization<br>direction', new THREE.Vector3(4.10, 0.98, 0.1), { fontSize: '18px' }),
  dirB: addLabel('Direction<br>of ray', new THREE.Vector3(4.70, 0.05, 0.1), { fontSize: '18px' }),
  panelB: addLabel('(b)', new THREE.Vector3(1.05, -2.33, 0.1), { fontSize: '18px' }),
  e0: addLabel(vecEHtml(), new THREE.Vector3(-2.76, 1.44, 0.1), { fontSize: '18px' }),
  e1: addLabel(vecEHtml(), new THREE.Vector3(-1.88, 0.66, 0.1), { fontSize: '18px' }),
  e2: addLabel(vecEHtml(), new THREE.Vector3(-2.20, -0.36, 0.1), { fontSize: '18px' }),
  e3: addLabel(vecEHtml(), new THREE.Vector3(-1.38, 0.64, 0.1), { fontSize: '18px' }),
  eT: addLabel(vecEHtml(), new THREE.Vector3(3.55, -0.93, 0.1), { fontSize: '18px' })
};

function setLabelVisible(entry, visible) {
  entry.div.style.visibility = visible ? 'visible' : 'hidden';
}

function pointAround(origin, radius, angleDeg, extraDeg = 0) {
  const a = THREE.MathUtils.degToRad(angleDeg + extraDeg);
  return new THREE.Vector3(origin.x + radius * Math.cos(a), origin.y + radius * Math.sin(a), 0.1);
}

let selectedIndex = null;
let axisAngle = 90;
let mode = 'Unpolarized only (a)';

function updateELabels() {
  const c = starGroup.position;
  labels.e0.pos.copy(pointAround(c, 0.86, 90, 7));
  labels.e1.pos.copy(pointAround(c, 0.98, 45, 5));
  labels.e2.pos.copy(pointAround(c, 1.00, 315, -8));
  labels.e3.pos.copy(pointAround(c, 1.02, 0, 4));

  const a = THREE.MathUtils.degToRad(axisAngle);
  const amp = selectedIndex === null ? 1 : Math.abs(Math.cos(THREE.MathUtils.degToRad(incomingAngles[selectedIndex]) - a));
  labels.eT.pos.set(
    transmittedArrow.position.x + Math.cos(a) * (0.42 * Math.max(amp, 0.2)) + 0.18,
    transmittedArrow.position.y + Math.sin(a) * (0.42 * Math.max(amp, 0.2)),
    0.1
  );
}

function updateLeaders() {
  const a = THREE.MathUtils.degToRad(axisAngle);
  const axisDir = new THREE.Vector3(Math.cos(a), Math.sin(a), 0);
  leaderAxis.userData.setPoints([
    new THREE.Vector3(2.35, 0.62, 0.10),
    filterCenterB.clone().add(axisDir.clone().multiplyScalar(0.36)).setZ(0.10)
  ]);
  leaderPol.userData.setPoints([
    new THREE.Vector3(4.15, 0.62, 0.10),
    transmittedArrow.position.clone().add(axisDir.clone().multiplyScalar(0.52)).setZ(0.10)
  ]);
  leaderRayB.userData.setPoints([
    new THREE.Vector3(4.60, -0.25, 0.10),
    rayEndB.clone().add(rayDir.clone().multiplyScalar(-0.42)).setZ(0.10)
  ]);
}

function updateAxis() {
  document.getElementById('axisReadout').textContent = `${axisAngle}°`;
  const rad = THREE.MathUtils.degToRad(axisAngle);
  axisArrow.rotation.z = rad;
  transmittedArrow.rotation.z = rad;

  let transmittedAmp = 1;
  if (selectedIndex !== null && mode.includes('Polarizer')) {
    const theta = THREE.MathUtils.degToRad(incomingAngles[selectedIndex]);
    transmittedAmp = Math.abs(Math.cos(theta - rad));
  }
  transmittedArrow.scale.x = 1.20 * transmittedAmp;

  parallelComp.rotation.z = rad;
  perpComp.rotation.z = rad + Math.PI / 2;
  if (selectedIndex !== null) {
    const theta = THREE.MathUtils.degToRad(incomingAngles[selectedIndex]);
    parallelComp.scale.x = 1.05 * Math.abs(Math.cos(theta - rad));
    perpComp.scale.x = 1.05 * Math.abs(Math.sin(theta - rad));
  }

  updateELabels();
  updateLeaders();

  const isB = mode.includes('Polarizer');
  setLabelVisible(labels.eT, isB && (selectedIndex === null || transmittedAmp > 0.03));
}

function selectIncoming(i) {
  if (!mode.includes('Polarizer')) {
    mode = 'Polarizer inserted (b)';
    document.getElementById('viewMode').value = mode;
  }

  selectedIndex = i;
  incomingArrows.forEach((arrow, j) => {
    setArrowOpacity(arrow, j === i ? 1 : 0.20);
    arrow.scale.y = j === i ? 1.34 : 1;
  });

  componentGroup.visible = true;
  componentGroup.position.copy(starGroup.position).setZ(0.11);
  updateAxis();
  applyMode(false);

  showPopup('Component selected by the filter',
    'The selected incoming electric field is resolved into a red component parallel to the filter axis and a faint gray component perpendicular to it. If the selected direction is perpendicular to the filter axis, the transmitted arrow shrinks all the way to zero.');
}

function clearSelection() {
  selectedIndex = null;
  incomingArrows.forEach(arrow => {
    setArrowOpacity(arrow, 1);
    arrow.scale.y = 1;
  });
  componentGroup.visible = false;
  updateAxis();
}

function applyMode(clear = true) {
  const isB = mode.includes('Polarizer');

  starGroup.position.copy(isB ? starB : starA);
  filterGroup.visible = isB;
  transmittedArrow.visible = isB;
  leaderGroup.visible = isB;
  componentGroup.visible = isB && selectedIndex !== null;
  updateRayForMode(isB);

  if (isB && selectedIndex !== null) {
    componentGroup.position.copy(starGroup.position).setZ(0.11);
  }
  if (!isB && clear) {
    selectedIndex = null;
    incomingArrows.forEach(arrow => {
      setArrowOpacity(arrow, 1);
      arrow.scale.y = 1;
    });
    componentGroup.visible = false;
  }

  labels.random.pos.set(isB ? starB.x - 0.02 : -3.0, isB ? starB.y + 1.05 : 1.70, 0.1);
  setLabelVisible(labels.dirA, !isB);
  setLabelVisible(labels.panelA, !isB);
  setLabelVisible(labels.filter, isB);
  setLabelVisible(labels.axis, isB);
  setLabelVisible(labels.pol, isB);
  setLabelVisible(labels.dirB, isB);
  setLabelVisible(labels.panelB, isB);

  updateAxis();
}

const uiAxis = document.getElementById('filterAxisAngle');
const uiMode = document.getElementById('viewMode');

uiAxis.addEventListener('input', () => {
  axisAngle = Number(uiAxis.value);
  updateAxis();
});

uiMode.addEventListener('change', () => {
  mode = uiMode.value;
  clearSelection();
  applyMode();
});

document.getElementById('clearSelection').addEventListener('click', () => {
  clearSelection();
  hidePopup();
});

const demoSteps = [
  {
    title: 'Random polarization before the filter',
    narration: 'The blue ray travels diagonally across the page while the red E arrows point in many transverse directions. This represents unpolarized light: no one electric-field direction is preferred.',
    state: { viewMode: 'Unpolarized only (a)', filterAxisAngle: 90 }
  },
  {
    title: 'Insert the polarizing filter',
    narration: 'The tan filter appears on the ray. Only the red E arrow aligned with the filter axis remains beyond it, making the transmitted light linearly polarized.',
    state: { viewMode: 'Polarizer inserted (b)', filterAxisAngle: 90 }
  },
  {
    title: 'Rotate the filter axis',
    narration: 'As the filter axis rotates, the outgoing red E arrow rotates with it. The polarization direction of the transmitted light is set by the filter, not by any one original random direction.',
    state: { viewMode: 'Polarizer inserted (b)', filterAxisAngle: 45 }
  },
  {
    title: 'Pick one incoming E arrow',
    narration: 'One incident E direction is isolated. Its projection along the filter axis is highlighted as the transmitted component, while the perpendicular component fades as the blocked part.',
    state: { viewMode: 'Polarizer inserted (b)', filterAxisAngle: 90, selectedIndex: 1 }
  }
];

let currentStep = 0;
function goToStep(i) {
  currentStep = Math.max(0, Math.min(demoSteps.length - 1, i));
  const step = demoSteps[currentStep];

  document.getElementById('stepTitle').textContent = step.title;
  document.getElementById('stepNarration').textContent = step.narration;
  uiMode.value = step.state.viewMode;
  uiAxis.value = step.state.filterAxisAngle;
  mode = step.state.viewMode;
  axisAngle = Number(step.state.filterAxisAngle);

  clearSelection();
  applyMode();
  if (step.state.selectedIndex !== undefined) selectIncoming(step.state.selectedIndex);
}
window.goToStep = goToStep;

document.getElementById('stepPrev').addEventListener('click', () => goToStep(currentStep - 1));
document.getElementById('stepNext').addEventListener('click', () => goToStep(currentStep + 1));

applyMode();
// @FIGURE_CODE_END

